3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose city already holds the maximum number of owners
10	 * ({@value #CAPACITY}), responding 409, before {@link BuildOwner} persists one over the
11	 * limit. City membership is counted via {@link Cities}.
12	 */
13	public class EnsureCityUnderCapacity {
14	
15	    static final int CAPACITY = 50;
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws CityAtCapacityException {
19	        if (Cities.countIn(ownerRepository, request.getCity()) >= CAPACITY) {
20	            throw new CityAtCapacityException(request.getCity(), CAPACITY);
21	        }
22	    }
23	}
