1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Rolls the effective registration date onto a business day: a Saturday or Sunday
8	 * &mdash; whether supplied in the request or defaulted by
9	 * {@link DefaultOwnerRegistrationDate} &mdash; moves forward to the following Monday.
10	 * Mutates the shared request in place so the adjusted date is the one the daily limit
11	 * counts against, the membership number's year segment is taken from, and
12	 * {@link BuildOwner} persists. Runs after {@link DefaultOwnerRegistrationDate}, so the
13	 * date is always present.
14	 */
15	public class RollRegistrationDateToBusinessDay {
16	
17	    public void service(@Val OwnerFieldsDto request) {
18	        request.setRegistrationDate(BusinessDays.rollForward(request.getRegistrationDate()));
19	    }
20	}
