1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the new owner's {@code namesakeCount}: the number of existing owners that share
9	 * the new owner's first and last name, compared case-insensitively. Runs after
10	 * {@link BuildOwner} (so the entity and its name exist) and before {@link SaveOwner}
11	 * persists the count, so the freshly created owner is not counted among its own
12	 * namesakes.
13	 */
14	public class AssignOwnerNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        long count = ownerRepository.findByLastName(owner.getLastName()).stream()
18	                .filter(existing -> equalsIgnoreCase(existing.getFirstName(), owner.getFirstName())
19	                        && equalsIgnoreCase(existing.getLastName(), owner.getLastName()))
20	                .count();
21	        owner.setNamesakeCount((int) count);
22	    }
23	
24	    private static boolean equalsIgnoreCase(String a, String b) {
25	        return a == null ? b == null : a.equalsIgnoreCase(b);
26	    }
27	}
