2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Shared business-day logic. A business day is Monday–Friday; a Saturday or Sunday
8	 * rolls forward to the following Monday. Every rule that must land on a business day
9	 * (the registration date, and therefore the daily limit and membership number derived
10	 * from it) uses this single definition.
11	 */
12	final class BusinessDays {
13	
14	    private BusinessDays() {
15	    }
16	
17	    /**
18	     * The given date if it is a business day, otherwise the following Monday.
19	     */
20	    static LocalDate rollForward(LocalDate date) {
21	        DayOfWeek day = date.getDayOfWeek();
22	        if (day == DayOfWeek.SATURDAY) {
23	            return date.plusDays(2);
24	        }
25	        if (day == DayOfWeek.SUNDAY) {
26	            return date.plusDays(1);
27	        }
28	        return date;
29	    }
30	}
